    return (timestamp: number) => {
      const target = this.targets.get(key);

      if (!target) {
        return;
      }

      const shouldAbort = this.onFrame(target, timestamp);

      if (!target.stopped && !shouldAbort) {
        this.scheduleFrame(key);
      } else {
        this.cancelFrame(key);
      }
    };
